# ruff: noqa: F401

from logging import Logger
from os import path
from pprint import pformat
from typing import Optional
from ta_tti_collector.collectors.tti_trace_streaming_collector import TtiTraceStreamingCollector
try:
    from ta_tti_collector.collectors.taf_l2stream3_collector import TafL2stream3Collector
except ImportError:
    pass
from ta_tti_collector.utils import get_simple_logger
from ta_tti_collector.telemetry import get_telemetry_instance


class UnknownAlias(Exception):
    pass


class UnknownBtsTypeException(Exception):
    pass


tl = get_telemetry_instance()

class TtiCollector(object):
    def __init__(self, dest_dir='/tmp/tti_trace_results', logger=None):
        # type: (str, Optional[Logger]) -> None
        self.logger = get_simple_logger(logger=logger, logger_name='tti_collector', stream=True,
                                        full_path=path.join(dest_dir, 'ta_tti_collector.log'))
        self._collector = None
        self.dest_dir = dest_dir

    def _create_collector_instance(self, value):
        """Factory method that creates proper tti collector instance type"""
        with tl.trace("create_collector_instance"):
            bts_values = value[list(value.keys())[0]]
            if 'enb' in bts_values:
                self._collector = TtiTraceStreamingCollector(dest_dir=self.dest_dir)
                tl.update("prepare_collector", 1, {"status": "success", "type": "ENB"})
            elif 'gnb' in bts_values:
                self._collector = TafL2stream3Collector(dest_dir=self.dest_dir)
                tl.update("prepare_collector", 1, {"status": "success", "type": "GNB"})
            else:
                tl.update("prepare_collector", 1, {"status": "fail"})
                raise UnknownBtsTypeException('Library could not recognize bts type from values {}'.format(bts_values))

    @property
    def register(self):
        """
        Register for aliases.

        Possible keys in register dict:

        r'{'alias1': {'cells': {1: 'ULDL'},
        r'            'enb': 2,
        r'            'UL': ['/tmp/TtiTraceServer1/tti_stream_cell_NAME_1_UL.dat_1585640760.dat'],
        r'            'DL': ['/tmp/TtiTraceServer1/tti_stream_cell_trace_1_DL_16Apr2020_14_36_05.dat']}}
        """
        self.logger.debug('Access registry: {}'.format(pformat(self._collector._register)))
        return self._collector._register

    @register.setter
    def register(self, value):
        # type: (dict)  -> None
        """Add value to registry property as dict."""
        if not self._collector:
            self._create_collector_instance(value)
        self._collector.register(value)

    def start_collecting(self, alias):
        self._collector.start_collecting(alias)

    def stop_collecting(self, alias):
        self._collector.stop_collecting(alias)

    def post_test_cleanup(self):
        # type: () -> None
        """Cleanup any hanging TTS process mess."""
        self._collector.post_test_cleanup()

    def renew_cellmapping(self):
        self._collector.renew_cellmapping()
